import std/[base64]
import tarpeek

let goodTar = base64.decode("")
let badCksum = base64.decode("")
let truncTar = base64.decode("")
const LongName = "very/long/prefix/path/segments/that/exceed/the/100/char/single/name/field/so/a/prefix/split/is/required/to/store/it/leaf.txt"

var failures = 0

proc check(cond: bool, msg: string) =
  if not cond:
    echo "FAIL: ", msg
    failures += 1

proc expectTarError(data: string, msg: string) =
  try:
    discard parseTar(data)
    echo "FAIL: expected TarError: ", msg
    failures += 1
  except TarError:
    discard

proc testDecodeAll() =
  let entries = parseTar(goodTar)
  check(entries.len == 3, "entry count " & $entries.len)
  if entries.len == 3:
    check(entries[0].name == "hello.txt", "name[0] " & entries[0].name)
    check(entries[0].kind == '0', "kind[0]")
    check(entries[0].size == 12, "size[0] " & $entries[0].size)
    check(entries[0].data == "Hello, tar!\n", "data[0] " & repr(entries[0].data))
    check(entries[1].name == "sub/dir/", "dir name " & entries[1].name)
    check(entries[1].kind == '5', "dir kind")
    check(entries[1].data == "", "dir data")
    check(entries[2].name == LongName, "long name: " & entries[2].name)
    check(entries[2].data == "leaf", "leaf data")

proc testBadChecksum() =
  expectTarError(badCksum, "corrupted checksum must raise")

proc testTruncated() =
  expectTarError(truncTar, "truncated file data must raise")

proc testEmpty() =
  check(parseTar("").len == 0, "empty input")

testDecodeAll()
testBadChecksum()
testTruncated()
testEmpty()

if failures == 0:
  echo "ALL TARPEEK TESTS PASSED"
else:
  echo $failures & " failures"
  quit(1)
